// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 2 ether);

        vm.prank(user);
        c.deposit{value: 1}();


        address alice = address(0x456);
        vm.deal(alice, 0);
        vm.prank(alice);

        bool ok;
        try c.deposit{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false, "Reference should revert on zero-value deposit, buggy should allow it");
    }
}
